import { createStore } from "solid-js";

// Silent: the trap reads `isServer` before its `const` declaration runs, which
// throws a ReferenceError, so no member of the store is read. A `const` alias
// carries the realm only to a read proved to run after its initializer.
function useTdzBaseQuery(options) {
  const [state] = createStore({ search: options.search });
  return new Proxy(state, {
    get(target, prop, receiver) {
      if (isServer) {
        return "server";
      }
      const isServer = typeof window === "undefined";
      return Reflect.get(target, prop, receiver);
    }
  });
}
export function useTdzQuery(options) {
  return useTdzBaseQuery(options);
}
